శూన్య vTaskMissedYield( శూన్య )
{
    traceENTER_vTaskMissedYield();

    /* Must be called from within a critical section. */
    xYieldPendings[ పోర్టు_GET_CORE_ID() ] = pdTRUE;

    traceRETURN_vTaskMissedYield();
}
